// 📁 src/app/pages/home/home.component.ts
// VERSIÓN ACTUALIZADA PARA FUNCIONAR CON EL HTML

import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { Observable, Subject, of } from 'rxjs';
import { takeUntil } from 'rxjs/operators';

// Importar desde la nueva arquitectura
import { Property } from '../../core/models/property.interface';
import { SearchParams } from '../../core/models/search.interface';
import { PropertyService } from '../../core/services/property.service';

@Component({
  selector: 'app-home',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule
  ],
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss']
})
export class HomeComponent implements OnInit, OnDestroy {
  
  // 🎯 DATOS REACTIVOS
  featuredProperties$: Observable<Property[]>;
  
  // 📊 ESTADO
  isLoading = true;
  searchError: string | null = null;
  
  // 🔍 FORM DATA
  searchData: SearchParams = {
    destination: '',
    checkIn: '',
    checkOut: '',
    guests: 2
  };
  
  // 🧹 CLEANUP
  private destroy$ = new Subject<void>();

  // 📅 COMPUTED PROPERTIES
  readonly today = new Date().toISOString().split('T')[0];
  readonly tomorrow = new Date(Date.now() + 86400000).toISOString().split('T')[0];

  // 🚀 SUGERENCIAS RÁPIDAS
  readonly quickSuggestions = [
    { destination: 'norte-centro', label: 'Norte Centro', icon: '🏢' },
    { destination: 'la-secreta', label: 'La Secreta', icon: '🏘️' },
    { destination: 'bosques-pinares', label: 'Bosques de Pinares', icon: '🌲' },
    { destination: 'ciudadela-del-cafe', label: 'Ciudadela del Café', icon: '☕' }
  ];

  // 🗺️ ZONAS DEL NORTE
  readonly zonasDelNorte = [
    {
      key: 'norte-centro',
      name: 'Norte Centro',
      description: 'Zona comercial y residencial, cerca del centro de la ciudad con excelente transporte público.',
      icon: '🏢',
      properties: '12'
    },
    {
      key: 'la-secreta',
      name: 'La Secreta',
      description: 'Barrio tranquilo y familiar, ideal para estadías largas con todos los servicios cerca.',
      icon: '🏘️',
      properties: '8'
    },
    {
      key: 'bosques-pinares',
      name: 'Bosques de Pinares',
      description: 'Zona exclusiva con amplias zonas verdes, perfecta para descanso y tranquilidad.',
      icon: '🌲',
      properties: '6'
    }
  ];

  // 🏷️ TIPOS DE PROPIEDADES
  private readonly propertyTypes = {
    'habitacion': 'Habitación Privada',
    'apartamento': 'Apartamento Completo',
    'casa': 'Casa Completa',
    'studio': 'Studio',
    'familiar': 'Habitación Familiar',
    'finca': 'Finca Cafetera',
    'cabana': 'Cabaña Ecológica',
    'hacienda': 'Hacienda Tradicional'
  };

  // 🏠 DATOS DE PRUEBA (mientras no haya servicio real)
  private readonly mockProperties: Property[] = [
    {
      id: '1',
      title: 'Finca Cafetera El Mirador',
      location: 'Salento, Quindío',
      description: 'Auténtica finca cafetera con vista panorámica al Valle de Cocora. Incluye tour completo del proceso del café y degustación.',
      pricePerNight: 85000,
      rating: 4.9,
      propertyType: 'finca',
      features: ['2 habitaciones', '1 baño', 'Cocina equipada'],
      image: 'https://images.unsplash.com/photo-1564013799919-ab600027ffc6?w=400&h=300&fit=crop',
      isFavorite: false,
      shortLocation: '',
      reviews: 0,
      reviewsCount: 0,
      images: [],
      amenities: [],
      experiences: [],
      includedExperiences: [],
      isSuperhost: false,
      hasOffers: false
    },
    {
      id: '2',
      title: 'Cabaña Palmas de Cera',
      location: 'Valle de Cocora, Salento',
      description: 'Cabaña ecológica en el corazón del Valle de Cocora, rodeada de las majestuosas palmas de cera más altas del mundo.',
      pricePerNight: 120000,
      rating: 4.8,
      propertyType: 'cabana',
      features: ['3 habitaciones', '2 baños', 'Chimenea'],
      image: 'https://images.unsplash.com/photo-1449824913935-59a10b8d2000?w=400&h=300&fit=crop',
      isFavorite: true,
      shortLocation: '',
      reviews: 0,
      reviewsCount: 0,
      images: [],
      amenities: [],
      experiences: [],
      includedExperiences: [],
      isSuperhost: false,
      hasOffers: false
    },
    {
      id: '3',
      title: 'Hacienda Balcón del Quindío',
      location: 'Filandia, Quindío',
      description: 'Elegante hacienda colonial con amplios jardines y vista espectacular desde el "Balcón del Quindío".',
      pricePerNight: 150000,
      rating: 4.7,
      propertyType: 'hacienda',
      features: ['4 habitaciones', '3 baños', 'Sala de estar'],
      image: 'https://images.unsplash.com/photo-1582268611958-ebfd161ef9cf?w=400&h=300&fit=crop',
      isFavorite: false,
      shortLocation: '',
      reviews: 0,
      reviewsCount: 0,
      images: [],
      amenities: [],
      experiences: [],
      includedExperiences: [],
      isSuperhost: false,
      hasOffers: false
    }
  ];

  constructor(
    private propertyService: PropertyService,
    private router: Router
  ) {
    // Usar datos mock o servicio real
    this.featuredProperties$ = this.propertyService.getFeaturedProperties() || of(this.mockProperties);
  }

  ngOnInit(): void {
    this.loadFeaturedProperties();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  // ================================
  // 🔄 DATA LOADING
  // ================================
  
  private loadFeaturedProperties(): void {
    // Simular loading
    setTimeout(() => {
      this.isLoading = false;
    }, 1000);

    this.featuredProperties$
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (properties) => {
          this.isLoading = false;
          console.log('✅ Propiedades cargadas:', properties.length);
        },
        error: (error) => {
          this.isLoading = false;
          console.error('❌ Error cargando habitaciones:', error);
        }
      });
  }

  // ================================
  // 🔍 SEARCH FUNCTIONALITY
  // ================================
  
  onSearchSubmit(form: any): void {
    if (form.valid) {
      this.performSearch(this.searchData);
    } else {
      this.searchError = 'Por favor completa todos los campos requeridos';
    }
  }

  private performSearch(params: SearchParams): void {
    if (!params.destination || !params.checkIn || !params.checkOut) {
      this.searchError = 'Por favor completa todos los campos';
      return;
    }

    this.searchError = null;
    
    this.router.navigate(['/search'], { 
      queryParams: {
        ...params,
        area: 'norte-armenia'
      }
    });
  }

  searchDestination(destination: string): void {
    const searchParams: SearchParams = {
      destination,
      checkIn: this.getDateString(1),
      checkOut: this.getDateString(3),
      guests: 2
    };

    this.performSearch(searchParams);
  }

  // ================================
  // 🏠 PROPERTY ACTIONS
  // ================================
  
  viewPropertyDetails(propertyId: string): void {
    console.log('🏠 Ver detalles de propiedad:', propertyId);
    
    if (this.propertyService.incrementPropertyViews) {
      this.propertyService.incrementPropertyViews(propertyId)
        .pipe(takeUntil(this.destroy$))
        .subscribe();
    }

    this.router.navigate(['/property', propertyId]);
  }

  toggleFavorite(propertyId: string, event: Event): void {
    event.stopPropagation();
    
    console.log('❤️ Toggle favorito:', propertyId);
    
    if (this.propertyService.toggleFavorite) {
      this.propertyService.toggleFavorite(propertyId)
        .pipe(takeUntil(this.destroy$))
        .subscribe({
          next: (isFavorite) => {
            console.log(`${isFavorite ? '❤️' : '🤍'} Favorito actualizado`);
          },
          error: (error) => console.error('❌ Error actualizando favorito:', error)
        });
    }
  }

  // ================================
  // 🛠️ UTILITY FUNCTIONS
  // ================================
  
  trackByPropertyId(index: number, property: Property): string {
    return property.id;
  }

  getPropertyTypeName(type: string): string {
    return this.propertyTypes[type as keyof typeof this.propertyTypes] || 'Alojamiento';
  }

  getPropertyFeatures(property: Property): string[] {
    if (property?.features && property.features.length > 0) {
      return property.features.slice(0, 3);
    }
    
    // Features por defecto si no hay datos
    return ['2 habitaciones', '1 baño', 'Cocina equipada'];
  }

  trackInteraction(action: string, data?: any): void {
    console.log(`📊 ${action}:`, data);
    
    if (action === 'contact_whatsapp') {
      const message = encodeURIComponent('Hola! Me interesa información sobre las habitaciones en el norte de Armenia');
      window.open(`https://wa.me/573001234567?text=${message}`, '_blank');
    }
  }

  viewAllProperties(): void {
    this.router.navigate(['/search'], {
      queryParams: {
        area: 'norte-armenia'
      }
    });
  }

  private getDateString(daysFromNow: number): string {
    const date = new Date();
    date.setDate(date.getDate() + daysFromNow);
    return date.toISOString().split('T')[0];
  }
}
